"""Brute-force solvers written from the problem definitions."""

from __future__ import annotations

from itertools import combinations
from typing import Any


def _has_clique(n: int, edges: list, k: int) -> bool:
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for subset in combinations(range(n), k):
        if all(adj[u][v] for u, v in combinations(subset, 2)):
            return True
    return False


def _has_independent_set(n: int, edges: list, k: int) -> bool:
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for subset in combinations(range(n), k):
        if not any(adj[u][v] for u, v in combinations(subset, 2)):
            return True
    return False


def solve_clique(instance: dict[str, Any]) -> bool:
    return _has_clique(instance["n"], instance["edges"], instance["k"])


def solve_independent_set(instance: dict[str, Any]) -> bool:
    return _has_independent_set(instance["n"], instance["edges"], instance["k"])
